async function metaWhatsAppWebhook(req,res,url){
  if(req.method==='GET'){
    const mode=url.searchParams.get('hub.mode'),token=url.searchParams.get('hub.verify_token'),challenge=url.searchParams.get('hub.challenge')||'';
    const ok=mode==='subscribe'&&all().officialConnections.some(c=>c.active!==false&&c.verifyToken===token);
    return ok?text(res,200,challenge):text(res,403,'Token de verificação inválido');
  }
  if(req.method!=='POST')return text(res,405,'Method not allowed');
  const payload=await body(req,8*1024*1024);try{
    for(const entry of payload.entry||[])for(const change of entry.changes||[]){const value=change.value||{},phoneNumberId=value.metadata?.phone_number_id,conn=all().officialConnections.find(c=>c.phoneNumberId===phoneNumberId);if(!conn)continue;
      for(const st of value.statuses||[]){const local=all().messages.find(m=>m.externalId===st.id);if(local){const status=String(st.status||'').toUpperCase();local.status=status==='DELIVERED'?'DELIVERED':status==='READ'?'READ':status==='FAILED'?'FAILED':local.status;local.meta={...(local.meta||{}),cloudStatus:st};save();emit('message.status',{conversationId:local.conversationId,message:local})}}
      const profileName=value.contacts?.[0]?.profile?.name||'';
      for(const m of value.messages||[]){const phone=normalizePhone(m.from),ct=upsertContactByPhone(phone,{name:profileName||phone,source:'WhatsApp Oficial',nameSource:profileName?'profile':'fallback'}),cv=ensureConversation(ct.id,conn.id,{status:'WAITING',ownerId:null,provider:'CLOUD_API'});let type=String(m.type||'text').toUpperCase(),bodyText='';if(m.text?.body)bodyText=m.text.body;else if(m.button?.text)bodyText=m.button.text;else if(m.interactive?.button_reply?.title)bodyText=m.interactive.button_reply.title;else if(m.interactive?.list_reply?.title)bodyText=m.interactive.list_reply.title;else bodyText=`[${type} recebido pela API Oficial]`;handleInboundConversationState(cv,{source:'CLOUD_API'});const rec=addMessage({conversationId:cv.id,direction:'IN',type:type==='TEXT'?'TEXT':type,body:bodyText,status:'DELIVERED',externalId:m.id||null,remoteJid:phone,provider:'CLOUD_API',meta:{cloud:m}});save();emit('message.received',{conversationId:cv.id,message:rec});emit('conversation.updated',{conversationId:cv.id});pushLog('OFFICIAL_MESSAGE_RECEIVED',{connectionId:conn.id,conversationId:cv.id,type})}
    }
  }catch(e){pushLog('OFFICIAL_WEBHOOK_ERROR',{error:e.message})}
  return json(res,200,{ok:true});
}

function serveFile(req,res,url){
  let rel=decodeURIComponent(url.pathname),base=publicDir;
  if(rel.startsWith('/uploads/')){base=uploadDir;rel=rel.slice('/uploads'.length)}
  if(rel==='/'||rel==='')rel='/index.html';
  let file=path.resolve(base,'.'+rel);
  if(!file.startsWith(path.resolve(base)))return text(res,403,'Forbidden');
  if(!fs.existsSync(file)||fs.statSync(file).isDirectory())file=path.join(publicDir,'index.html');
  try{
    const ext=path.extname(file).toLowerCase(),stat=fs.statSync(file),size=stat.size,contentType=mime[ext]||'application/octet-stream';
    const cache=['.html','.js','.css'].includes(ext)?'no-cache':'public, max-age=3600';
    const baseHeaders={'Content-Type':contentType,'Cache-Control':cache,'Accept-Ranges':'bytes'};
    if(req.method==='HEAD'){res.writeHead(200,{...baseHeaders,'Content-Length':size});return res.end()}
    const range=String(req.headers.range||'');
    if(range){
      const match=/bytes=(\d*)-(\d*)/.exec(range);
      if(match){
        let start=match[1]?Number(match[1]):0,end=match[2]?Number(match[2]):size-1;
        if(!match[1]&&match[2]){const suffix=Number(match[2]);start=Math.max(0,size-suffix);end=size-1}
        if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||start>=size||end<start){res.writeHead(416,{...baseHeaders,'Content-Range':`bytes */${size}`});return res.end()}
        end=Math.min(end,size-1);
        res.writeHead(206,{...baseHeaders,'Content-Range':`bytes ${start}-${end}/${size}`,'Content-Length':end-start+1});
        return fs.createReadStream(file,{start,end}).pipe(res)
      }
    }
    res.writeHead(200,{...baseHeaders,'Content-Length':size});
    return fs.createReadStream(file).pipe(res)
  }catch{return text(res,404,'Not found')}
}
const server=http.createServer(async(req,res)=>{const url=new URL(req.url,`http://${req.headers.host||'localhost'}`);try{if(req.method==='GET'&&url.pathname==='/healthz')return json(res,200,{ok:true,version:APP_VERSION,uptimeSeconds:Math.round(process.uptime())});if(req.method==='GET'&&url.pathname==='/__balbino/version')return json(res,200,{ok:true,version:APP_VERSION});if(url.pathname==='/webhooks/meta/whatsapp')return await metaWhatsAppWebhook(req,res,url);if(url.pathname.startsWith('/api/integracao/'))return await integrationApi(req,res,url);if(url.pathname.startsWith('/external/'))return await externalApi(req,res,url);if(url.pathname.startsWith('/api/'))return await api(req,res,url);if(url.pathname.startsWith('/uploads/')&&!currentUser(req))return json(res,401,{error:'AUTH_REQUIRED'});return serveFile(req,res,url)}catch(e){const errorId=crypto.randomBytes(3).toString('hex').toUpperCase();console.error(`[${errorId}]`,e);pushLog('SERVER_ERROR',{errorId,path:url.pathname,error:e.message,stack:e.stack});if(!res.headersSent)return json(res,500,{error:`Erro interno ${errorId}. Consulte Logs / Auditoria.`});try{res.end()}catch{}}});

